103	impl SinkConfig for DatabendConfig {
104	    async fn build(&self, _cx: SinkContext) -> crate::Result<(VectorSink, Healthcheck)> {
105	        let ua = format!("vector/{}", vector_version());
106	        let auth = self.auth.choose_one(&self.endpoint.auth)?;
107	        let authority = self
108	            .endpoint
109	            .uri
110	            .authority()
111	            .ok_or("Endpoint missing authority")?;
112	        let endpoint = match self.endpoint.uri.scheme().map(|s| s.as_str()) {
113	            Some("databend") => self.endpoint.to_string(),
114	            // for backward compatibility, build DSN from endpoint
115	            Some("http") => format!("databend://{}/?sslmode=disable", authority),
116	            Some("https") => format!("databend://{}", authority),
117	            None => {
118	                return Err("Missing scheme for Databend endpoint. Expected `databend`.".into());
119	            }
120	            Some(s) => {
121	                return Err(format!("Unsupported scheme for Databend endpoint: {}", s).into());
122	            }
123	        };
124	        let mut endpoint = url::Url::parse(&endpoint)?;
125	        match auth {
126	            Some(Auth::Basic { user, password }) => {
127	                let _ = endpoint.set_username(&user);
128	                let _ = endpoint.set_password(Some(password.inner()));
129	            }
130	            Some(Auth::Bearer { .. }) => {
131	                return Err("Bearer authentication is not supported currently".into());
132	            }
133	            None => {}
134	        }
135	        if let Some(database) = &self.database {
136	            endpoint.set_path(&format!("/{}", database));
137	        }
138	        let endpoint = endpoint.to_string();
139	        let health_client = DatabendAPIClient::new(&endpoint, Some(ua.clone())).await?;
140	        let healthcheck = select_one(health_client).boxed();
141	
142	        let request_settings = self.request.into_settings();
143	        let batch_settings = self.batch.into_batcher_settings()?;
144	
145	        let mut file_format_options = BTreeMap::new();
146	        let compression = match self.compression {
147	            DatabendCompression::Gzip => {
148	                file_format_options.insert("compression", "GZIP");
149	                Compression::gzip_default()
150	            }
151	            DatabendCompression::None => {
152	                file_format_options.insert("compression", "NONE");
153	                Compression::None
154	            }
155	        };
156	        let encoding: EncodingConfig = self.encoding.clone().into();
157	        let serializer = match self.encoding.config() {
158	            DatabendSerializerConfig::Json(_) => {
159	                file_format_options.insert("type", "NDJSON");
160	                file_format_options.insert("missing_field_as", self.missing_field_as.as_str());
161	                encoding.build()?
162	            }
163	            DatabendSerializerConfig::Csv(_) => {
164	                file_format_options.insert("type", "CSV");
165	                file_format_options.insert("field_delimiter", ",");
166	                file_format_options.insert("record_delimiter", "\n");
167	                file_format_options.insert("skip_header", "0");
168	                encoding.build()?
169	            }
170	        };
171	        let framer = FramingConfig::NewlineDelimited.build();
172	        let transformer = encoding.transformer();
173	
174	        let mut copy_options = BTreeMap::new();
175	        copy_options.insert("purge", "true");
176	
177	        let client = DatabendAPIClient::new(&endpoint, Some(ua)).await?;
178	        let service = DatabendService::new(
179	            client,
180	            self.table.clone(),
181	            file_format_options,
182	            copy_options,
183	        )?;
184	        let service = ServiceBuilder::new()
185	            .settings(request_settings, DatabendRetryLogic)
186	            .service(service);
187	
188	        let encoder = Encoder::<Framer>::new(framer, serializer);
189	        let request_builder = DatabendRequestBuilder::new(compression, (transformer, encoder));
190	
191	        let sink = DatabendSink::new(batch_settings, request_builder, service);
192	
193	        Ok((VectorSink::from_event_streamsink(sink), healthcheck))
194	    }
